from pathlib import Pathfrom typing import Dict, Optional, Unionimport loggingfrom swat_toolkit.core.output_manager import SWATOutputManagerfrom swat_toolkit.core.txinout import TxInOutfrom swat_toolkit.io.writers import HRUWriter, SoilLayerWriterfrom swat_toolkit.io.parameters import SWATParamfrom swat_toolkit.run import SWATRunlogger = logging.getLogger(__name__)class SWATProject:    """        >>> project = SWATProject(        ...     project_dir="D:/SWAT/my_project",        ...     swat_exe="D:/SWAT/swat2012.exe"        ... )        >>> project.update_parameters({'CN2': 75})        >>> project.run()        >>> df = project.output.read_reach()    """    def __init__(            self, txinout_dir: Union[str, Path],                swat_exe: Union[str, Path],            param_file: Optional[str] = None    ):        self.txinout = TxInOut(str(txinout_dir))        if not txinout_dir.exists():            raise FileNotFoundError(f"TxtInOut directory not found: {txinout_dir}")        self.swat_exe = Path(swat_exe)        if not self.swat_exe.exists():            raise FileNotFoundError(f"SWAT executable not found: {self.swat_exe}")        if param_file:            self.param_file = SWATParam(param_file)        else:            default_param = self.project_dir / "swatParam.txt"            if default_param.exists():                self.param_file = SWATParam(str(default_param))            else:                self.param_file = None                logger.warning("No parameter file provided")        self.swat_run = SWATRun(str(self.swat_exe))        # ==========================================        self._output_manager = None        self._observed_data = {}        self._analysis = None        self._visualization = None        logger.info(f"SWAT Project initialized: {self.txinout}")        logger.info(f"Found {self.txinout.number_hru} HRUs in {self.txinout.number_sub} subbasins")    # ==================== Properties (Lazy Loading) ====================    @property    def output(self) -> SWATOutputManager:        if self._output_manager is None:            self._output_manager = SWATOutputManager(self.txinout.directory)        return self._output_manager    @property    def analysis(self):        """Access analysis module (lazy loading)"""        if self._analysis is None:            from swat_toolkit.analysis.statistics import SWATAnalysis            self._analysis = SWATAnalysis(self)        return self._analysis    @property    def viz(self):        """Access visualization module (lazy loading)"""        if self._visualization is None:            from swat_toolkit.visualization.visualization import SWATVisualization            self._visualization = SWATVisualization(self.analysis)        return self._visualization    # ==================== Parameter Management ====================    def update_parameters(            self,            param_dict: Dict,            target_hrus: Optional[list] = None    ):        """        Update SWAT parameters across HRU files        Args:            param_dict: Dictionary {param_name: value}            target_hrus: List of HRU IDs to update (None = all HRUs)        Examples:            >>> project.update_parameters({'CN2': 75, 'ALPHA_BF': 0.048})            >>> project.update_parameters({'CN2': 80}, target_hrus=[1, 2, 3])        """        if self.param_file is None:            raise ValueError("No parameter file loaded")        # Group parameters by file extension        param_by_ext = self.param_file.group_param_by_ext(param_dict)        updated_count = 0        for ext, params in param_by_ext.items():            files = self.txinout.find_files_ext(ext)            for file_path in files:                # Check if this HRU should be updated                if target_hrus is not None:                    file_stem = Path(file_path).stem.lstrip('0')                    if int(file_stem) not in target_hrus:                        continue                # Update file                if ext == '.sol':                    writer = SoilLayerWriter(file_path)                else:                    writer = HRUWriter(file_path)                writer.update_param(params, self.param_file)                writer.save()                updated_count += 1        logger.info(f"Updated {updated_count} files with parameters: {list(param_dict.keys())}")    def get_current_parameter_values(self, param_names: list, hru_id: int = None):        """        Get current parameter values from HRU files        Args:            param_names: List of parameter names            hru_id: Specific HRU ID (None = first HRU)        Returns:            Dictionary of current values        """        if self.param_file is None:            raise ValueError("No parameter file loaded")        # Get a sample HRU file        if hru_id:            hru_files = [f for f in self.txinout.find_files_ext('.hru')                         if Path(f).stem.lstrip('0') == str(hru_id)]            if not hru_files:                raise ValueError(f"HRU {hru_id} not found")            sample_file = hru_files[0]        else:            hru_files = self.txinout.find_files_ext('.hru')            sample_file = hru_files[0] if hru_files else None        if not sample_file:            raise ValueError("No HRU files found")        # Read current values        reader = HRUWriter(sample_file)        current_values = {}        for pname in param_names:            param = self.param_file.get(pname)            line = reader[param.line]            value_str = line[param.start:param.end].strip()            try:                current_values[pname] = float(value_str)            except ValueError:                current_values[pname] = None        return current_values    # ==================== Simulation ====================    def run(self, clear_output_cache: bool = True):        logger.info("Running SWAT simulation...")        self.swat_run.run(str(self.txinout.directory))        if clear_output_cache:            self.clear_output_cache()        logger.info("SWAT simulation completed")    def clear_output_cache(self):        """Clear cached output data"""        if self._output_manager is not None:            self._output_manager.clear_cache()            logger.debug("Output cache cleared")    # ==================== Observed Data Management ====================    def load_observed_data(self, name: str, file_path: str, **kwargs):        """        Load observed data for comparison        Args:            name: Name identifier for this dataset            file_path: Path to observed data file            **kwargs: Additional arguments for pd.read_csv        Examples:            >>> project.load_observed_data('flow', 'observed_flow.csv',            ...                           parse_dates=['date'])        """        from swat_toolkit.io.observed_data import ObservedData        self._observed_data[name] = ObservedData(file_path, **kwargs)        logger.info(f"Loaded observed data '{name}' from {file_path}")        return self._observed_data[name]    def get_observed_data(self, name: str):        """Get loaded observed dataset"""        if name not in self._observed_data:            raise KeyError(f"Observed data '{name}' not loaded")        return self._observed_data[name]    # ==================== Information Methods ====================    def info(self):        """Print project information"""        print("=" * 60)        print(f"SWAT Project: {self.project_dir.name}")        print("=" * 60)        print(f"Project Directory: {self.project_dir}")        print(f"SWAT Executable: {self.swat_exe}")        print(f"TxtInOut: {self.txinout.directory}")        print(f"Number of Subbasins: {self.txinout.number_sub}")        print(f"Number of HRUs: {self.txinout.number_hru}")        if self.param_file:            print(f"Parameter File: Loaded ({len(self.param_file.params)} parameters)")        else:            print("Parameter File: Not loaded")        print(f"Observed Datasets: {len(self._observed_data)}")        if self._observed_data:            for name in self._observed_data.keys():                print(f"  - {name}")        print("=" * 60)    def list_parameters(self):        """List all available parameters"""        if self.param_file is None:            raise ValueError("No parameter file loaded")        import pandas as pd        params_list = []        for name, param in self.param_file.params.items():            params_list.append({                'Parameter': name,                'Extension': param.ext,                'Min': param.vmin,                'Max': param.vmax,                'Decimals': param.round            })        df = pd.DataFrame(params_list)        return df.sort_values('Parameter')    def __repr__(self):        return (f"SWATProject '{self.txinout.directory}')', "                f"\n hrus={self.txinout.number_hru}, "                f"\n subs={self.txinout.number_sub})")